head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
// 호출메뉴ID를 식별하기 위한 함수사용
// 상장관련공통함수
// 세션정보를 얻기위한 함수사용

scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05324.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF05324.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "관리종목지정내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05324.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (scwin.vIsurCd !== "") {
            await scwin.search();
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05324.img_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05324.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05324.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function() {
    try {
        window.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05324.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
        if (cmb_RegistTyp.getSelectedIndex() === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
            cmb_RegistTyp.focus();
            return true;
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame(cmb_RegistTyp.BindColVal, "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05324.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;

        // 관리종목지정업무구분코드 값 넘겨야함
        await scwin.newpreCreateFrame(dts_List.getCellData(dts_List.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05324.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_iSU_CD_onclick
 * @description btn_iSU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_iSU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        // fn_PopFindIsu(fr_SecuGrpId);
        $c.lc.fn_PopFindIsuAll(scwin.fr_SecuGrpId); // jackal_11.05.12
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05324.btn_iSU_CD_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/administrativeIssue.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 예비심사청구제출기관 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    await scwin.search();
    // jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD === "D") {
        img_Regist.setDisabled(true);
        img_Regist.setBackgroundImage("../img/btn_new_d.gif");
    } else {
        img_Regist.setDisabled(false);
        img_Regist.setBackgroundImage("../img/btn_new.gif");
    }
};

/**
 * @method
 * @name getParUpdate
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vIsurCd; // 발행기관코드값
    arrPar[1] = txb_ISU_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts_List.getCellData(dts_List.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값

    return arrPar.length;
};

/**
 * @method
 * @name getParNew
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = scwin.vIsurCd; // 발행기관코드값
    arrPar[1] = txb_ISU_NM.getValue(); // 종목명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값

};

/**
 * @method
 * @name newpreCreateFrame
 * @description newpre Create Frame 처리
 * @param {*} arg arg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    2:관리종목사유및상장폐지기준일변경
    3:상장폐지기준일변경
    4:관리종목지정해제
     */
    switch (arg) {
        case "0":
            const options = {
                id: "ULDSTF05325",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정",
                type: "browserPopup",
                width: "620px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05325.gfm", options);
            break;
        case "1":
            const options2 = {
                id: "ULDSTF05326",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 사유변경",
                type: "browserPopup",
                width: "620px",
                height: "520px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05326.gfm", options2);
            break;
        case "4":
            const options3 = {
                id: "ULDSTF05327",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 해제",
                type: "browserPopup",
                width: "620px",
                height: "450px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05327.gfm", options3);
            break;
    }

    // fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.
    cmb_RegistTyp.setSelectedIndex(0);
};
